-- Synthetic recruiting privacy/receipt checks; all state rolls back.
update public.organizations set status='active';
insert into private.career_policy(organization_id,enabled,employee_count,review_until) values('20000000-0000-4000-8000-000000000001',true,1,now()+interval '90 days');
create function pg_temp.career_body() returns text language sql as $$select '{"key":"82000000-0000-4000-8000-000000000001","proof":"aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa","profile":{"role":"home_support","name":"Synthetic Applicant","email":"applicant@example.invalid","phone":"5550000000","city":"DeKalb","skills":["Furniture assembly"],"experience":"Synthetic experience assembling furniture.","availability":"Weekday mornings","travel":"yes","authorized":"yes","adult":true,"privacy":true,"notice":"careers-2026-11-01"},"resume":{"name":"resume.pdf","mime":"application/pdf","bytes":37,"sha256":"e61b3b51a58150c71d536a091f55207751311496b5227be8981a4b1e61d24f55","content":"JVBERi0xLjcKU3ludGhldGljIGZpeHR1cmUgb25seQolJUVPRg=="}}'::text$$;
set local role service_role;
select set_config('request.jwt.claims','{"role":"service_role"}',true);
select pg_temp.assert_true(public.career_public_status('20000000-0000-4000-8000-000000000001')->>'accepting'='true','reviewed interest board open');
select public.career_apply('20000000-0000-4000-8000-000000000001',pg_temp.career_body(),repeat('b',64));
select public.career_apply('20000000-0000-4000-8000-000000000001',pg_temp.career_body(),repeat('b',64));
select pg_temp.assert_true(public.career_resolve('20000000-0000-4000-8000-000000000001','82000000-0000-4000-8000-000000000001',repeat('a',64),repeat('b',64))->>'outcome'='received','receipt recovery');
select public.career_resolve('20000000-0000-4000-8000-000000000001','82000000-0000-4000-8000-000000000002',repeat('a',64),repeat('b',64));
do $$begin begin perform public.career_apply('20000000-0000-4000-8000-000000000001',replace(pg_temp.career_body(),'82000000-0000-4000-8000-000000000001','82000000-0000-4000-8000-000000000002'),repeat('b',64));raise exception 'TEST FAILED late application';exception when raise_exception then if sqlerrm<>'ATTEMPT_CLOSED' then raise;end if;end;end$$;
do $$begin begin perform public.career_resolve('20000000-0000-4000-8000-000000000001','82000000-0000-4000-8000-000000000001',repeat('c',64),repeat('b',64));raise exception 'TEST FAILED wrong receipt proof';exception when insufficient_privilege then null;end;end$$;
reset role;
select pg_temp.assert_true((select count(*)=1 from private.career_applications),'exact retry stores one applicant');
select pg_temp.assert_true((select count(*)=0 from public.outbox),'application never sends unapproved email');
set local role authenticated;
select set_config('request.jwt.claims','{"role":"authenticated","sub":"00000000-0000-4000-8000-000000000001","session_id":"10000000-0000-4000-8000-000000000001"}',true);
select pg_temp.assert_true(public.career_owner_workspace('20000000-0000-4000-8000-000000000001')->>'total'='1','owner private inbox');
select pg_temp.assert_true(public.career_resume_owner('20000000-0000-4000-8000-000000000001',(public.career_owner_workspace('20000000-0000-4000-8000-000000000001')->'items'->0->>'id')::uuid)->>'sha256'='e61b3b51a58150c71d536a091f55207751311496b5227be8981a4b1e61d24f55','owner byte/hash-verified resume');
do $$begin begin perform public.career_owner_command('20000000-0000-4000-8000-000000000001','{"organization":"20000000-0000-4000-8000-000000000001","key":"83000000-0000-4000-8000-000000000001","revision":1,"action":"configure","employeeCount":15,"accepting":true,"reviewed":true}');raise exception 'TEST FAILED undisclosed 15+ recruiting';exception when raise_exception then if sqlerrm<>'PAY_DISCLOSURE_REQUIRED' then raise;end if;end;end$$;
do $$declare target uuid;body text;begin
 target:=(public.career_owner_workspace('20000000-0000-4000-8000-000000000001')->'items'->0->>'id')::uuid;
 body:=jsonb_build_object('organization','20000000-0000-4000-8000-000000000001','key','83000000-0000-4000-8000-000000000002','revision',1,'action','review','id',target,'status','contacted','note','Synthetic actual contact note','confirmedContact',false)::text;
 begin perform public.career_owner_command('20000000-0000-4000-8000-000000000001',body);raise exception 'TEST FAILED fabricated contact';exception when raise_exception then if sqlerrm<>'VALIDATION' then raise;end if;end;
 body:=replace(body,'false','true');perform public.career_owner_command('20000000-0000-4000-8000-000000000001',body);perform public.career_owner_command('20000000-0000-4000-8000-000000000001',body);
 perform pg_temp.assert_true(public.career_owner_workspace('20000000-0000-4000-8000-000000000001')->'items'->0->>'revision'='2','review exact replay');
 perform pg_temp.assert_true(jsonb_array_length(public.career_owner_workspace('20000000-0000-4000-8000-000000000001')->'items'->0->'history')=1,'one retained actual-contact attestation');
end$$;
select public.career_owner_command('20000000-0000-4000-8000-000000000001','{"organization":"20000000-0000-4000-8000-000000000001","key":"83000000-0000-4000-8000-000000000003","revision":1,"action":"configure","employeeCount":15,"accepting":false,"reviewed":true}');
select set_config('request.jwt.claims','{"role":"authenticated","sub":"00000000-0000-4000-8000-000000000002","session_id":"10000000-0000-4000-8000-000000000002"}',true);
do $$begin begin perform public.career_owner_workspace('20000000-0000-4000-8000-000000000001');raise exception 'TEST FAILED cross-company applicant read';exception when insufficient_privilege then null;end;end$$;
reset role;
insert into public.memberships(organization_id,user_id,role) values('20000000-0000-4000-8000-000000000001','00000000-0000-4000-8000-000000000004','admin');
set local role authenticated;
select set_config('request.jwt.claims','{"role":"authenticated","sub":"00000000-0000-4000-8000-000000000004","session_id":"10000000-0000-4000-8000-000000000004"}',true);
do $$begin begin perform public.career_owner_workspace('20000000-0000-4000-8000-000000000001');raise exception 'TEST FAILED admin reads private hiring';exception when insufficient_privilege then null;end;end$$;
reset role;
set local role service_role;
select set_config('request.jwt.claims','{"role":"service_role"}',true);
select pg_temp.assert_true(public.career_public_status('20000000-0000-4000-8000-000000000001')->>'accepting'='false','15+ pause visible to public board');
reset role;
rollback;
